async () => {
const sel=document.querySelector('select');
sel.value='50';sel.dispatchEvent(new Event('change',{bubbles:true}));
await new Promise(r=>setTimeout(r,300));
const next=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()=='Next');
const seen=new Map();let pages=0;
for(let i=0;i<40;i++){
 const cells=[...document.querySelectorAll('td')].map(c=>c.textContent.trim());
 for(let j=0;j+6<cells.length;j+=7)seen.set(cells[j],cells.slice(j,j+7));
 pages++;
 if(next.disabled)break;
 next.click();await new Promise(r=>setTimeout(r,200));
}
const rows=[...seen.values()].filter(r=>r[3]=='West'&&r[5]=='Refunded');
const total=rows.reduce((s,r)=>s+parseFloat(r[6].replace(/[$,]/g,'')),0);
return {pages,n:seen.size,count:rows.length,total:total.toFixed(2),label:document.body.innerText.match(/Page \d+ of \d+/)[0]};
}

